{
  "title": "CSCI-141: Computer Science I - Foundations",
  "learningObjectives": [
    "Define and apply the core components of computational thinking, including precise problem statements, input/output examples, and algorithmic logic.",
    "Represent algorithms using pseudo code and a programming language, demonstrating functional and imperative techniques, control structures, and data ab",
    "Evaluate correctness, testing, and debugging by comparing intended behavior with observable results, including boundary and error cases."
  ],
  "beats": [
    {
      "title": "Computational Thinking Foundations",
      "claim": "Programming begins with precise problem statements, input and output examples, and algorithms written independently of syntax.",
      "example": "A problem statement defines what the program must do, while input and output examples specify the expected behavior for specific cases.",
      "visualDirection": "Display a flowchart showing the sequence of steps from problem statement to algorithm to code, with arrows indicating the flow of information.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Variables and State",
      "claim": "Variables represent values and state, expressions compute values, and control structures select or repeat operations.",
      "example": "A variable stores a value that can change over time, while expressions compute new values based on existing ones, and control structures determine which operations to execute.",
      "visualDirection": "Show a table with columns for variable name, initial value, and final value, illustrating how state changes during execution.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Functions and Decomposition",
      "claim": "Functions decompose a solution into named operations with parameters and results.",
      "example": "A function takes input parameters, performs a specific operation, and returns a result, breaking down complex problems into manageable parts.",
      "visualDirection": "Display a diagram of a function with input parameters, internal operations, and a return value, showing how it encapsulates a specific task.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Recursion and Base Cases",
      "claim": "Recursion solves a problem through smaller instances and requires a base case.",
      "example": "A recursive function calls itself with a smaller input until it reaches a base case, at which point it stops and returns a value.",
      "visualDirection": "Show a tree diagram representing the recursive calls, with the base case at the bottom and each level representing a smaller instance of the problem.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Lists and Data Structures",
      "claim": "Lists represent ordered sequences, stacks use last-in first-out access, queues use first-in first-out access, trees represent hierarchy, and graphs represent connected entities.",
      "example": "A list stores items in order, a stack adds and removes items from the top, a queue adds items to the back and removes from the front, a tree organizes items hierarchically, and a graph connects entities with edges.",
      "visualDirection": "Display a series of diagrams showing a list, stack, queue, tree, and graph, with labels indicating the order of elements and connections.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Control Structures",
      "claim": "Control structures select or repeat operations, enabling conditional execution and loops.",
      "example": "An if statement executes a block of code if a condition is true, while a for loop repeats a block of code a specified number of times.",
      "visualDirection": "Show a flowchart with an if statement branching into two paths and a for loop with a counter variable, illustrating how control structures direct execution.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Search and Sort Algorithms",
      "claim": "Searching and sorting algorithms depend on representation and invariants.",
      "example": "A search algorithm finds a specific item in a list, while a sort algorithm arranges items in order, both relying on the data structure used and specific invariants to maintain correctness.",
      "visualDirection": "Display a table with columns for algorithm name, input, output, and invariant, showing how different algorithms handle data and maintain specific properties.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Correctness and Testing",
      "claim": "Correctness arguments, tests, tracing, and debugging compare intended behavior with observable results, including boundary and error cases.",
      "example": "Tests verify that the program behaves as expected for various inputs, including edge cases, while tracing follows the execution step by step to identify errors.",
      "visualDirection": "Show a table with columns for test case, expected output, actual output, and status, illustrating how tests compare intended and observable behavior.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Debugging Techniques",
      "claim": "Debugging separates syntax, runtime, and logical failures, while decomposition and abstraction reduce the number of interacting concerns.",
      "example": "Debugging involves identifying and fixing errors in the code, such as syntax errors, runtime errors, or logical errors, by breaking the problem into smaller parts and focusing on one concern at a time.",
      "visualDirection": "Display a flowchart showing the process of debugging, with steps for identifying the error, isolating the issue, and applying a fix, with arrows indicating the flow of the process.",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "An end-of-term project requires a pseudo code solution and an implementation, ensuring students apply all learned concepts.",
      "example": "The project involves writing pseudo code to describe the algorithm, then implementing the algorithm in a programming language, and finally testing the implementation to ensure correctness.",
      "visualDirection": "Show a checklist with items for pseudo code, implementation, testing, and documentation, with checkboxes indicating completion of each step.",
      "sourceIds": ["rit-csci-141"]
    }
  ]
}
